    target[Table.GLOBAL to "app_ops_constants"] = Explanation("App ops specific settings. This is encoded as a key=value list, separated by commas. Ex: \"state_settle_time=10000\" The following keys are supported: top_state_settle_time (long) fg_service_state_settle_time (long) bg_state_settle_time (long) Type: string", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#17202", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "app_standby_enabled"] = Explanation("Whether or not App Standby feature is enabled by system. This controls throttling of apps based on usage patterns and predictions. Platform will turn on this feature if both this flag and .ADAPTIVE_BATTERY_MANAGEMENT_ENABLED is on. Type: int (0 for false, 1 for true) Default: 1", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#17649", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "app_time_limit_usage_source"] = Explanation("App time limit usage source setting. This controls which app in a task will be considered the source of usage when calculating app usage time limits. 1 -> task root app 2 -> current app Any other value defaults to task root app. Need to reboot the device for this setting to take effect.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#17445", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "apply_ramping_ringer"] = Explanation("Legacy/deprecated in Android 17. Whether applying ramping ringer on incoming phone call ringtone. 1 = apply ramping ringer 0 = do not apply ramping ringer", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#14320", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "appop_history_parameters"] = Explanation("Appop history parameters. These parameters are represented by a comma-delimited key-value list. The following strings are supported as keys: mode (int) baseIntervalMillis (long) intervalMultiplier (int) Ex: \"mode=HISTORICAL_MODE_ENABLED_ACTIVE,baseIntervalMillis=1000,intervalMultiplier=10\"", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#20502", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "are_user_disabled_hdr_formats_allowed"] = Explanation("Whether or not user-disabled HDR formats are allowed. The value is boolean (1 or 0). The value '1' means the user preference for disabling a format is ignored, and the disabled formats are still reported to apps (if supported by the display). The value '0' means the user-disabled formats are not reported to apps, even if the display supports them. The list of formats disabled by the user are contained in the USER_DISABLED_HDR_FORMATS setting. This list is treated as empty when the value of this setting is '1'.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#18685", Risk.UNKNOWN, documentationOnly=true)
