    target[Table.GLOBAL to "auto_revoke_parameters"] = Explanation("Auto revoke parameters. These parameters are represented by a comma-delimited key-value list. enabledForPreRApps (bolean) unusedThresholdMs (long) checkFrequencyMs (long) Ex: \"enabledForPreRApps=false,unusedThresholdMs=7776000000,checkFrequencyMs=1296000000\"", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#20525", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "auto_time"] = Explanation("Value to specify if the device's UTC system clock should be set automatically, e.g. using telephony signals like NITZ, or other sources like GNSS or NTP. Prefer android.app.time.TimeManager API calls to determine the state of automatic time detection instead of directly observing this setting as it may be ignored by the time_detector service under various conditions. 1=yes, 0=no (manual)", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#14516", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "auto_time_zone"] = Explanation("Value to specify if the device's time zone system property should be set automatically, e.g. using telephony signals like MCC and NITZ, or other mechanisms like the location. Prefer android.app.time.TimeManager API calls to determine the state of automatic time zone detection instead of directly observing this setting as it may be ignored by the time_zone_detector service under various conditions. 1=yes, 0=no (manual).", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#14529", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "auto_time_zone_explicit"] = Explanation("Records whether an explicit preference for .AUTO_TIME_ZONE has been expressed instead of the current value being the default. This value is used to tell if the .AUTO_TIME_ZONE value can be influenced by experiment flags that alter the setting's value for internal testers: once the user indicates a preference they leave the experiment, only users that are still using the default will be affected by the flag. Since .AUTO_TIME_ZONE can be altered by components besides the system server, and not just via the time_zone_detector logic that sets this value, this isn't guaranteed to be set when the device diverges from the default in all cases. Important AOSP system components like SettingsUI do use the time_zone_detector APIs. 1=\"has been set explicitly\"", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#14542", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "auto_wifi"] = Explanation("Whether the auto wifi toggle setting is enabled.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#20924", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "autofill_compat_mode_allowed_packages"] = Explanation("Legacy/deprecated in Android 17. The packages allowlisted to be run in autofill compatibility mode. The list of packages is \":\" colon delimited, and each entry has the name of the package and an optional list of url bar resource ids (the list is delimited by brackets&mdash[ and ]&mdash and is also comma delimited). For example, a list with 3 packages p1, p2, and p3, where package p1 have one id (url_bar, p2 has none, and p3 have 2 ids url_foo and url_bas) would be p1[url_bar]:p2:p3[url_foo,url_bas]", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#19252", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "autofill_logging_level"] = Explanation("Level of autofill logging. Valid values are android.view.autofill.AutofillManager.NO_LOGGING, android.view.autofill.AutofillManager.FLAG_ADD_CLIENT_DEBUG, or android.view.autofill.AutofillManager.FLAG_ADD_CLIENT_VERBOSE.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#19273", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "autofill_max_partitions_size"] = Explanation("Maximum number of partitions that can be allowed in an autofill session.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#19286", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "autofill_max_visible_datasets"] = Explanation("Maximum number of visible datasets in the Autofill dataset picker UI, or 0 to use the default value from resources.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#19294", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "automatic_power_save_mode"] = Explanation("Whether battery saver is currently set to trigger based on percentage, dynamic power savings trigger, or none. See AutoPowerSaveModeTriggers for accepted values.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#18207", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "average_time_to_discharge"] = Explanation("Legacy/deprecated in Android 17. A long value indicating how long the system battery takes to deplete from 100% to 0% on average based on historical drain rates. See .BATTERY_ESTIMATES_LAST_UPDATE_TIME for the last time this value was updated.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#18267", Risk.UNKNOWN, documentationOnly=true)
