    target[Table.GLOBAL to "backup_agent_timeout_parameters"] = Explanation("Backup and restore agent timeout parameters. These parameters are represented by a comma-delimited key-value list. The following strings are supported as keys: kv_backup_agent_timeout_millis (long) full_backup_agent_timeout_millis (long) shared_backup_agent_timeout_millis (long) restore_agent_timeout_millis (long) restore_agent_finished_timeout_millis (long) They map to milliseconds represented as longs. Ex: \"kv_backup_agent_timeout_millis=30000,full_backup_agent_timeout_millis=300000\"", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#20351", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "battery_charging_state_enforce_level"] = Explanation("Threshold battery level to enforce battery state as charging. That means when battery level is equal to or higher than this threshold, it is always considered charging, even if battery level lowered. This is used as an override for constants defined in BatteryStatsImpl. Its purposes are: Ease of experimentation Customization of different device", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#20558", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "battery_charging_state_update_delay"] = Explanation("Delay for sending ACTION_CHARGING after device is plugged in. This is used as an override for constants defined in BatteryStatsImpl. Its purposes are: Ease of experimentation Customization of different device", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#20543", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "battery_discharge_duration_threshold"] = Explanation("Threshold values for the duration and level of a discharge cycle, under which we log discharge cycle info.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#16542", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "battery_estimates_last_update_time"] = Explanation("Legacy/deprecated in Android 17. A long indicating the epoch time in milliseconds when .TIME_REMAINING_ESTIMATE_MILLIS, .TIME_REMAINING_ESTIMATE_BASED_ON_USAGE, and .AVERAGE_TIME_TO_DISCHARGE were last updated.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#18279", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "battery_saver_constants"] = Explanation("Battery Saver specific settings This is encoded as a key=value list, separated by commas. Ex: \"vibration_disabled=true,adjust_brightness_factor=0.5\" The following keys are supported: advertise_is_enabled (boolean) datasaver_disabled (boolean) enable_night_mode (boolean) launch_boost_disabled (boolean) vibration_disabled (boolean) animation_disabled (boolean) soundtrigger_disabled (boolean) fullbackup_deferred (boolean) keyvaluebackup_deferred (boolean) firewall_disabled (boolean) gps_mode (int) adjust_brightness_disabled (boolean) adjust_brightness_factor (float) force_all_apps_standby (boolean) force_background_check (boolean) optional_sensors_disabled (boolean) aod_disabled (boolean) quick_doze_enabled (boolean)", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#17257", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "battery_saver_device_specific_constants"] = Explanation("Battery Saver device specific settings This is encoded as a key=value list, separated by commas. The following keys are supported: cpufreq-i (list of \"core-number:frequency\" pairs concatenated with /) cpufreq-n (list of \"core-number:frequency\" pairs concatenated with /) See com.android.server.power.batterysaver.BatterySaverPolicy for the details.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#17293", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "battery_saver_mode"] = Explanation("The device's battery saver mode, which can be one of the following: -BATTERY_SAVER_MODE_NONE -BATTERY_SAVER_MODE_LIGHT -BATTERY_SAVER_MODE_TRADITIONAL_WATCH -BATTERY_SAVER_MODE_TIME_ONLY -BATTERY_SAVER_MODE_CUSTOM", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#21308", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "battery_stats_constants"] = Explanation("BatteryStats specific settings. This is encoded as a key=value list, separated by commas. Ex: \"foo=1,bar=true\" The following keys are supported: track_cpu_times_by_proc_state (boolean) track_cpu_active_cluster_time (boolean) read_binary_cpu_time (boolean) proc_state_cpu_times_read_delay_ms (long) external_stats_collection_rate_limit_ms (long) battery_level_collection_delay_ms (long) max_history_files (int) max_history_buffer_kb (int) battery_charged_delay_ms (int) battery_charging_enforce_level (int) Type: string", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#17570", Risk.UNKNOWN, documentationOnly=true)
