    target[Table.GLOBAL to "battery_tip_constants"] = Explanation("Battery tip specific settings This is encoded as a key=value list, separated by commas. Ex: \"battery_tip_enabled=true,summary_enabled=true,high_usage_enabled=true,\" \"high_usage_app_count=3,reduced_battery_enabled=false,reduced_battery_percent=50,\" \"high_usage_battery_draining=25,high_usage_period_ms=3000\" The following keys are supported: battery_tip_enabled (boolean) summary_enabled (boolean) battery_saver_tip_enabled (boolean) high_usage_enabled (boolean) high_usage_app_count (int) high_usage_period_ms (long) high_usage_battery_draining (int) app_restriction_enabled (boolean) reduced_battery_enabled (boolean) reduced_battery_percent (int) low_battery_enabled (boolean) low_battery_hour (int)", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#17312", Risk.UNKNOWN, documentationOnly=true)
