    target[Table.GLOBAL to "bcast_fg_constants"] = Explanation("Broadcast dispatch tuning parameters specific to foreground broadcasts. This is encoded as a key=value list, separated by commas. Ex: \"foo=1,bar=true\" The following keys are supported: bcast_timeout (long) bcast_slow_time (long) bcast_deferral (long) bcast_deferral_decay_factor (float) bcast_deferral_floor (long) bcast_allow_bg_activity_start_timeout (long)", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#17607", Risk.UNKNOWN, documentationOnly=true)
