    target[Table.GLOBAL to "mute_alarm_stream_with_ringer_mode_user_preference"] = Explanation("The user's choice for whether or not Alarm stream should always be muted with Ringer. Note that this is different from .MUTE_ALARM_STREAM_WITH_RINGER_MODE, which controls the real state of whether or not the Alarm stream and Ringer association occurs. The two Settings are not necessarily equal, if the final decision for the association depends on factors beyond the user's preference.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#16486", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "native_binder_stats"] = Explanation("Native binder stats settings. These parameters are represented by a comma-delimited key-value list. The following strings are supported as keys: enabled (boolean) process_sharding (int) spam_sharding (int) call_sharding (int) system_process_sharding (int) system_spam_sharding (int) system_call_sharding (int)", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#20416", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "native_flags_health_check_enabled"] = Explanation("Whether we've enabled native flags health check on this device. Takes effect on reboot. The value \"1\" enables native flags health check; otherwise it's disabled.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#20465", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "network_avoid_bad_wifi"] = Explanation("Whether to automatically switch away from wifi networks that lose Internet access. Only meaningful if config_networkAvoidBadWifi is set to 0, otherwise the system always avoids such networks. Valid values are: 0: Don't avoid bad wifi, don't prompt the user. Get stuck on bad wifi like it's 2013. null: Ask the user whether to switch away from bad wifi. 1: Avoid bad wifi.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#15871", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "network_default_daily_multipath_quota_bytes"] = Explanation("Default daily multipath budget used by ConnectivityManager.getMultipathPreference() on metered networks. This default quota is only used if quota could not be determined from data plan or data limit/warning set by the user.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#15896", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "network_location_opt_in"] = Explanation("Whether the user has consented for network location provider (NLP). This setting key will only be used once during OOBE to set NLP initial value through the companion app ToS. This setting key will be synced over from Companion and corresponding toggle in GMS will be enabled.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#21620", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "network_metered_multipath_preference"] = Explanation("User setting for ConnectivityManager.getMeteredMultipathPreference(). This value may be overridden by the system based on device or application state. If null, the value specified by config_networkMeteredMultipathPreference is used.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#15885", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "network_preference"] = Explanation("User preference for which network(s) should be used. Only the connectivity service should touch this.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#15378", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "network_recommendations_enabled"] = Explanation("Legacy/deprecated in Android 17. Value to specify if network recommendations from com.android.server.NetworkScoreService are enabled. Type: int Valid values: -1 = Forced off 0 = Disabled 1 = Enabled Most readers of this setting should simply check if value == 1 to determine the enabled state.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#16123", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "network_recommendations_package"] = Explanation("Legacy/deprecated in Android 17. Which package name to use for network recommendations. If null, network recommendations will neither be requested nor accepted. Use NetworkScoreManager.getActiveScorerPackage() to read this value and NetworkScoreManager.setActiveScorer(String) to write it. Type: string - package name", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#16143", Risk.UNKNOWN, documentationOnly=true)
