    target[Table.GLOBAL to "nitz_network_disconnect_retention"] = Explanation("If the device connects to a telephony network and was disconnected from a telephony network for less than this time, a previously received NITZ signal can be restored. This value is in milliseconds. It is used for telephony-based time and time zone detection.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#15425", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "nitz_update_diff"] = Explanation("If Unix epoch time between two NITZ signals is greater than this value then the second signal cannot be ignored. This value is in milliseconds. It is used for telephony-based time and time zone detection.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#15403", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "nitz_update_spacing"] = Explanation("If the elapsed realtime between two NITZ signals is greater than this value then the second signal cannot be ignored. This value is in milliseconds. It is used for telephony-based time and time zone detection.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#15414", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "notification_bubbles"] = Explanation("Legacy/deprecated in Android 17. Whether the notification bubbles are globally enabled The value is boolean (1 or 0).", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#14292", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "notification_snooze_options"] = Explanation("The list of snooze options for notifications This is encoded as a key=value list, separated by commas. Ex: \"default=60,options_array=15:30:60:120\" The following keys are supported: default (int) options_array (int[]) All delays in integer minutes. Array order is respected. Options will be used in order up to the maximum allowed by the UI.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#20223", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "nr_nsa_tracking_screen_off_mode"] = Explanation("For 5G NSA capable devices, determines whether NR tracking indications are on when the screen is off. Values are: 0: off - All 5G NSA tracking indications are off when the screen is off. 1: extended - All 5G NSA tracking indications are on when the screen is off as long as the device is camped on 5G NSA (5G icon is showing in status bar). If the device is not camped on 5G NSA, tracking indications are off. 2: always on - All 5G NSA tracking indications are on whether the screen is on or off.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#20605", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "ntp_server"] = Explanation("SNTP client config: The preferred NTP server. This setting overrides the static config.xml configuration when present and valid. The legacy form is the NTP server name as a string. Newer code should use the form: ntp://{server name}[:port] (the standard NTP port, 123, is used if not specified). The settings value can consist of a pipe (\"|\") delimited list of server names or ntp:// URIs. When present, all server name / ntp:// URIs must be valid or the entire setting value will be ignored and Android's xml config will be used. For example, the following examples are valid: \"time.android.com\" \"ntp://time.android.com\" \"ntp://time.android.com:123\" \"time.android.com|time.other\" \"ntp://time.android.com:123|ntp://time.other:123\" \"time.android.com|ntp://time.other:123\"", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#15436", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "ntp_timeout"] = Explanation("SNTP client config: Timeout to wait for an NTP server response. This setting overrides the static config.xml configuration when present and valid. The value is the timeout in milliseconds. It must be > 0.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#15463", Risk.UNKNOWN, documentationOnly=true)
