    target[Table.GLOBAL to "one_handed_keyguard_side"] = Explanation("In one handed mode, which side the keyguard should be on. Allowable values are one of the ONE_HANDED_KEYGUARD_SIDE_* constants.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#19524", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "ota_disable_automatic_update"] = Explanation("Whether to disable the automatic scheduling of system updates. 1 = system updates won't be automatically scheduled (will always present notification instead). 0 = system updates will be automatically scheduled. (default)", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#15524", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "overlay_display_devices"] = Explanation("Overlay display devices setting. The associated value is a specially formatted string that describes the size and density of simulated secondary display devices. Format: [display1];[display2];... with each display specified as: [mode1]|[mode2]|...,[flag1],[flag2],... with each mode specified as: [width]x[height]/[densityDpi] Supported flags: secure: creates a secure display own_content_only: only shows this display's own content should_show_system_decorations: always shows system decorations fixed_content_mode: does not allow the content mode switch Example: 1280x720/213: make one overlay that is 1280x720 at 213dpi. 1920x1080/320,secure;1280x720/213: make two overlays, the first at 1080p and secure; the second at 720p. 1920x1080/320|3840x2160/640: make one overlay that is 1920x1080 at 213dpi by default, but can also be upscaled to 3840x2160 at 640dpi by the system if the display device allows. If the value is empty, then no overlay display devices are created.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#16499", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "override_desktop_experience_features"] = Explanation("Whether to override the availability of the desktop experiences features on the device. With desktop experiences enabled, secondary displays can be used to run apps, in desktop mode by default. Otherwise they can only be used for mirroring.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#14976", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "override_desktop_mode_features"] = Explanation("Whether to override the availability of the desktop mode on the main display of the device. If on, users can make move an app to the desktop, allowing a freeform windowing experience.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#14986", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "override_settings_provider_restore_any_version"] = Explanation("If set to 1, SettingsProvider's restoreAnyVersion=\"true\" attribute will be ignored and restoring to lower version of platform API will be skipped.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#19218", Risk.UNKNOWN, documentationOnly=true)
