    target[Table.GLOBAL to "pdp_watchdog_error_poll_count"] = Explanation("The number of polls to perform (at .PDP_WATCHDOG_ERROR_POLL_INTERVAL_MS) after hitting .PDP_WATCHDOG_TRIGGER_PACKET_COUNT before attempting data connection recovery.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#15643", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "pdp_watchdog_error_poll_interval_ms"] = Explanation("The interval in milliseconds at which to check packet counts on the mobile data interface after .PDP_WATCHDOG_TRIGGER_PACKET_COUNT outgoing packets has been reached without incoming packets.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#15623", Risk.UNKNOWN, documentationOnly=true)
