    target[Table.GLOBAL to "power_button_suppression_delay_after_gesture_wake"] = Explanation("The amount of time to suppress \"power-off\" from the power button after the device has woken due to a gesture (lifting the phone). Since users have learned to hit the power button immediately when lifting their device, it can cause the device to turn off if a gesture has just woken the device. This value tells us the milliseconds to wait after a gesture before \"power-off\" via power-button is functional again. A value of 0 is no delay, and reverts to the old behavior.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#20583", Risk.UNKNOWN, documentationOnly=true)
