    target[Table.GLOBAL to "wifi_always_requested"] = Explanation("Whether the wifi data connection should remain active even when higher priority networks like Ethernet are active, to keep both networks. In the case where higher priority networks are connected, wifi will be unused unless an application explicitly requests to use it. See ConnectivityService for more info. (0 = disabled, 1 = enabled)", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#15267", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "wifi_badging_thresholds"] = Explanation("The thresholds of the wifi throughput badging (SD, HD etc.) as a comma-delimited list of colon-delimited key-value pairs. The key is the badging enum value defined in android.net.ScoredNetwork and the value is the minimum sustained network throughput in kbps required for the badge. For example: \"10:3000,20:5000,30:25000\"", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#15914", Risk.UNKNOWN, documentationOnly=true)
