    target[Table.GLOBAL to "wifi_display_wps_config"] = Explanation("WPS Configuration method used by Wifi display, this setting only takes effect when WIFI_DISPLAY_CERTIFICATION_ON is 1 (enabled). Possible values are: WpsInfo.INVALID: use default WPS method chosen by framework WpsInfo.PBC : use Push button WpsInfo.KEYPAD : use Keypad WpsInfo.DISPLAY: use Display", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#15943", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "wifi_enhanced_auto_join"] = Explanation("whether frameworks handles wifi auto-join", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#16282", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "wifi_ephemeral_out_of_range_timeout_ms"] = Explanation("Timeout for ephemeral networks when all known BSSIDs go out of range. We will disconnect from an ephemeral network if there is no BSSID for that network with a non-null score that has been seen in this time period. If this is less than or equal to zero, we use a more conservative behavior and only check for a non-null score from the currently connected or target BSSID.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#16413", Risk.UNKNOWN, documentationOnly=true)
