    target[Table.GLOBAL to "wifi_frequency_band"] = Explanation("The operational wifi frequency band Set to one of WifiManager.WIFI_FREQUENCY_BAND_AUTO, WifiManager.WIFI_FREQUENCY_BAND_5GHZ or WifiManager.WIFI_FREQUENCY_BAND_2GHZ", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#16391", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "wifi_idle_ms"] = Explanation("The interval in milliseconds after which Wi-Fi is considered idle. When idle, it is possible for the device to be switched from Wi-Fi to the mobile data network.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#16010", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "wifi_max_dhcp_retry_count"] = Explanation("The maximum number of times we will retry a connection to an access point for which we have failed in acquiring an IP address from DHCP. A value of N means that we will make N+1 connection attempts in all.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#16363", Risk.UNKNOWN, documentationOnly=true)
