private fun sourcePart15(target: MutableMap<Pair<Table,String>,Explanation>) {
    target[Table.GLOBAL to "wifi_network_show_rssi"] = Explanation("whether settings show RSSI", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#16290", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "wifi_networks_available_notification_on"] = Explanation("Legacy/deprecated in Android 17. Whether to notify the user of open networks. If not connected and the scan results have an open network, we will put this notification up. If we attempt to connect to a network or the open network(s) disappear, we remove the notification. When we show the notification, we will not show it again for android.provider.Settings.Secure.WIFI_NETWORKS_AVAILABLE_REPEAT_DELAY time.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#15959", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "wifi_networks_available_repeat_delay"] = Explanation("Legacy/deprecated in Android 17. Delay (in seconds) before repeating the Wi-Fi networks available notification. Connecting to a network will reset the timer.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#15983", Risk.UNKNOWN, documentationOnly=true)
    target[Table.GLOBAL to "wifi_num_open_networks_kept"] = Explanation("Legacy/deprecated in Android 17. When the number of open networks exceeds this number, the least-recently-used excess networks will be removed.", "Edit effects have not been assessed for this key. Source documentation describes its intended meaning, but does not establish that a direct write is supported or safe on this Pixel.", "https://android.googlesource.com/platform/frameworks/base/+/94b4c163b7dfe5ce3607f7bb8456f9573f7de57d/core/java/android/provider/Settings.java#16019", Risk.UNKNOWN, documentationOnly=true)
